/**
 * Route inventory for the BoardReadyOps QA audit.
 *
 * Generated by hand from `apps/web/app/**\/page.tsx`, not scanned at runtime, because the
 * audit needs to know per-route auth/DB requirements and safe fixture ids that only a human
 * (or an agent reading the route source) can supply — a directory walk alone can't tell you
 * that `/repositories/[repositoryId]` 404s without both a session and DATABASE_URL, or which
 * ids are demo-safe.
 *
 * `tests/unit/web/*.test.ts` already covers component-level rendering for every route below;
 * this inventory exists for the black-box, server-rendered, real-browser audit in
 * `tests/e2e/qa-audit.spec.ts` — a different failure class (hydration, console errors, axe
 * violations against actual computed styles, real navigation).
 *
 * When a new `page.tsx` is added under `apps/web/app`, add it here too.
 * `tests/e2e/route-inventory-coverage.spec.ts` fails the build if the two drift apart.
 */

export type RouteAuth = "public" | "authenticated";

export type QaRoute = {
  /** Stable id used in reports and `--grep` filters. */
  id: string;
  /** Path to request, with `:param` placeholders already substituted. */
  path: string;
  /** Human label for reports. */
  label: string;
  auth: RouteAuth;
  /** True if the route's real content requires DATABASE_URL (no demo/fixture fallback). */
  requiresDb: boolean;
  /** Skip this route's dynamic content entirely without DATABASE_URL, rather than auditing a stub. */
  skipWithoutDb?: boolean;
  /** Extra internal links this page is expected to expose, for the link-integrity check to prioritize. */
  expectedLinkPrefixes?: string[];
};

