export const errorStates = [
  { id: "not-found", path: "/this-route-does-not-exist", label: "Global 404" },
  { id: "run-not-found", path: `/runs/${missingRunId}`, label: "Run not found" },
] as const;

export function routeById(id: string): QaRoute {
  const route = routes.find((r) => r.id === id);
  if (!route) throw new Error(`Unknown QA route id: ${id}`);
  return route;
}
